    "question": "Trường hợp không có thỏa thuận về xử lý tài sản bảo đảm, Agribank nơi cấp tín dụng phải thực hiện xử lý tài sản bảo đảm kể từ ngày thông báo về việc xử lý tài sản bảo đảm với thời hạn như thế nào?",
